<script setup lang="ts">
import type { ApiSuccess } from '~/types/api'
definePageMeta({layout:'dashboard',middleware:'auth'});useHead({title:'Ressources humaines'})
type Hr={id:string;userId:string;employmentType:string;startDate:string|null;endDate:string|null;skills:string[];notes:string|null;absences:{id:string;type:string;status:string;startDate:string;endDate:string}[];trainings:{id:string;title:string;status:string}[];reviews:{id:string;reviewDate:string}[]}
const {data,error,refresh}=await useFetch<ApiSuccess<Hr[]>>('/api/hr');const profiles=computed(()=>data.value?.data??[]);const date=(v:string|null)=>v?new Date(v).toLocaleDateString('fr-FR'):'—'
</script>
<template><div><div class="page-head"><div><h1>Ressources humaines</h1><p>Profils internes, compétences, absences, formations et évaluations.</p></div><button class="btn btn-secondary" type="button" @click="refresh()">Actualiser</button></div><div v-if="error" class="alert alert-error">Impossible de charger les données RH.</div><div v-else-if="!profiles.length" class="empty-state">Aucun profil RH enregistré.</div><div v-else class="table-wrap"><table><thead><tr><th>Profil</th><th>Type</th><th>Période</th><th>Compétences</th><th>Absences</th><th>Formations</th></tr></thead><tbody><tr v-for="profile in profiles" :key="profile.id"><td><strong>{{ profile.userId }}</strong></td><td>{{ profile.employmentType }}</td><td>{{ date(profile.startDate) }} → {{ date(profile.endDate) }}</td><td>{{ profile.skills.slice(0,3).join(', ') || '—' }}</td><td>{{ profile.absences.length }}</td><td>{{ profile.trainings.length }}</td></tr></tbody></table></div></div></template>
